    {
        "title": "先求底面积",
        "description": "底面积 $=\\pi r^2=\\pi\\times 4^2=16\\pi\\text{ cm}^2$。",
        "bubbleText": "先把圆底算出来，再往上乘高度，就像一层一层叠起来。",
        "bubblePos": {
            "x": 536.0,
            "y": 476.0
        },
        "arrowTarget": {
            "x": 275.0,
            "y": 130.0
        }
