    {
        "title": "算出体积",
        "description": "体积 $=16\\pi\\times 12=192\\pi\\text{ cm}^3$。",
        "bubbleText": "把底面积再乘上 12cm，高度一加进去，整个笔筒的容量就出来啦。",
        "bubblePos": {
            "x": 536.0,
            "y": 476.0
        },
        "arrowTarget": {
            "x": 205.0,
            "y": 512.0
        }
    },
